function radioElements(e){const o=document.querySelectorAll(e);o.forEach((function(o){o.addEventListener("click",(function(){const o=this.closest(".group");if(!o)return;const t=o.querySelectorAll(e);t.forEach((function(e){e.classList.remove("active")}));this.classList.add("active")}))}))}function removeModal(e){console.log("remove modal");const o=document.querySelector(e);const t=o.children;if(!o||!t)return;Array.from(t).forEach((function(e){if(!e.classList.contains("active"))return;e.classList.remove("active")}));document.body.style.overflow="auto"}function openModal(e){console.log("open modal");const o=document.querySelector(e);console.log(o);const t=o.children;console.log(t);if(!o||!t)return;Array.from(t).forEach((function(e){if(e.classList.contains("not-active"))return;e.classList.add("active")}));document.body.style.overflow="hidden"}function getPriceOf(e){console.log("getPrice of event")}function getDirection(){document.querySelector("#direction-show").classList.add("active");document.querySelector("#description-show").classList.remove("active")}function getDescription(){document.querySelector("#direction-show").classList.remove("active");document.querySelector("#description-show").classList.add("active")}